LOAD vgi;
ATTACH 'asn1' (TYPE vgi, LOCATION './target/release/asn1-worker');
SET search_path = 'asn1.main';

-- Decode any BER/DER blob to JSON, to self-describing JSON, and to a dump.
SELECT decode(from_hex('3003020105'));                 -- '[5]'
SELECT to_json(payload), dump(payload) FROM read_blob('s3://pki/*.der');

-- Resolve OIDs and inventory every OID in a blob.
SELECT oid_name('1.2.840.113549.1.1.11');              -- 'sha256WithRSAEncryption'
SELECT oids(data) FROM blobs;                          -- LIST<STRUCT(oid,name,path)>

-- Robust, verify-free triage: well-formedness with a classified failure kind.
SELECT well_formed(data) FROM unknown_blobs WHERE NOT (well_formed(data)).ok;

-- Shred a CMS SignedData and join embedded signer certs to vgi-x509.
SELECT s.digest_alg, s.sig_alg, s.signing_time, s.signer_cert_sha256
FROM asn1.main.cms_signers(read_blob('codesign.p7s')) s;

LOAD vgi;
ATTACH 'barcode' (TYPE vgi, LOCATION './target/release/barcode-worker');
SET search_path = 'barcode.main';

-- Decode the first barcode in an image BLOB.
SELECT decode_barcode(content) AS text,
       barcode_format(content) AS format
FROM read_blob('label.png');
-- → 'vgi-barcode', 'QR_CODE'

-- Generate a QR-code PNG, then round-trip it.
SELECT decode_barcode(generate_qr('hi'));        -- → 'hi'

-- Generate an EAN-13 barcode PNG.
SELECT generate_barcode('5901234123457', 'EAN_13');

-- Every barcode found in one image (table function).
SELECT * FROM decode_barcodes(generate_qr('multi'));
-- seq | format  | text
--   0 | QR_CODE | multi

-- Discover the supported formats.
SELECT * FROM barcode_formats();

INSTALL vgi FROM community; LOAD vgi; LOAD inet;
ATTACH 'bgp' (TYPE vgi, LOCATION '/path/to/bgp-worker');

-- every route covering a prefix, ordered by AS-path length (leak/hijack triage)
SELECT peer_asn, origin_asn, as_path,
       bgp.main.path_length(as_path) AS hops, next_hop
FROM bgp.main.read_rib('https://routeviews.org/.../rib.20260629.0000.bz2')
WHERE prefix::INET >>= '203.0.113.5'::INET           -- core inet containment
ORDER BY hops;

-- announcements vs withdrawals in an update stream
SELECT message_type, count(*)
FROM bgp.main.read_updates('/dumps/updates.20260629.gz')
GROUP BY 1;

